// ZIP code lookup states
const [matchedSites, setMatchedSites] = useState<DonationSite[]>([]);
const [searchExpanded, setSearchExpanded] = useState<boolean>(false);
const [clientZipCode, setClientZipCode] = useState<string>("");

// Auto-population logic for Cleaning Donation - Gather
useEffect(() => {
    if (selectedSubTemplate === 'Cleaning Donation – Gather' && selectedPatient) {
        // Extract ZIP code
        const zipMatch = selectedPatient.address?.match(/\b\d{5}\b/);
        const zip = zipMatch ? zipMatch[0] : "";
        setClientZipCode(zip);

        if (zip) {
            const { sites, isExpanded } = lookupDonationSites(zip, 'Cleaning');
            setMatchedSites(sites);
            setSearchExpanded(isExpanded);

            // Format the resource text for insertion into context
            const resourcesHeader = language === 'es' ? "Recursos locales identificados:\n" : "Identified local resources:\n";
            const resourceLines = sites.map(s => {
                const isOld = (dateStr: string) => {
                    const verifiedDate = new Date(dateStr);
                    const currentDate = new Date();
                    const diffTime = Math.abs(currentDate.getTime() - verifiedDate.getTime());
                    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                    return diffDays > 90;
                };
                const verificationFlag = isOld(s.lastVerifiedDate) 
                    ? (language === 'es' ? " (¡REQUIERE VERIFICACIÓN TELEFÓNICA!)" : " (NEEDS PHONE VERIFICATION!)")
                    : "";
                return `• ${s.organization} – ${s.address}, ${s.city}, FL ${s.zip}. Tel: ${s.phone}. (Verificado: ${s.lastVerifiedDate}${verificationFlag})`;
            }).join('\n');

            const fullResourceText = `\n\n${resourcesHeader}${resourceLines}`;

            // Set context if it doesn't already contain the matching text
            setPatientInfo(prev => {
                if (prev.context.includes(sites[0]?.organization || "---")) {
                    return prev;
                }
                const cleanContext = prev.context.replace(/\n\n(Identified local resources:|Recursos locales identificados:)[\s\S]*/g, "");
                return {
                    ...prev,
                    context: cleanContext ? `${cleanContext}${fullResourceText}` : resourceLines
                };
            });
        } else {
            setMatchedSites([]);
            setSearchExpanded(false);
        }
    } else {
        setMatchedSites([]);
        setSearchExpanded(false);
        setClientZipCode("");
    }
}, [selectedSubTemplate, selectedPatient, language]);

